function authErrorMessage(error){
 if(error?.name==='MissingIdentityError')return 'خدمة تسجيل الدخول غير متاحة حالياً. تواصل مع مسؤول الموقع.';
 if(error?.status===429)return 'طلبات كثيرة خلال وقت قصير. انتظر بضع دقائق قبل إعادة المحاولة.';
 if(error?.status>=500)return 'تعذر إكمال الطلب لدى خدمة الدخول أو إرسال البريد. أعد المحاولة لاحقاً، وتواصل مع مسؤول الموقع إذا استمر الخلل.';
 if(/confirm|verified/i.test(error?.message||''))return 'يجب تأكيد البريد الإلكتروني أو قبول الدعوة قبل الدخول. راجع رسالة التفعيل والبريد غير المرغوب فيه.';
 if(error?.status===401||error?.status===400)return 'تعذر التحقق من بيانات الدخول. تحقق من البريد وكلمة المرور، ومن إنشاء حسابك وقبول الدعوة.';
 if(error?.status===403)return 'العملية غير مسموحة. تواصل مع مسؤول الموقع للتحقق من دعوتك وإعدادات التسجيل.';
 return 'تعذر إكمال الطلب. تحقق من الاتصال والبيانات ثم أعد المحاولة.';
}
