 useEffect(()=>{if(!modal)return;const previous=document.activeElement,dialog=document.querySelector('[role=dialog]');const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const focusable=()=>Array.from(dialog?.querySelectorAll('button:not(:disabled),input,select,a[href]')||[]);focusable()[0]?.focus();const key=e=>{if(e.key==='Escape')setModal(null);if(e.key==='Tab'){const all=focusable(),first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);previous?.focus?.()}},[storedModal]);
 async function mutate(path,body,method='POST'){if(saving.current)return false;if(isDemo){notify('أنت في العرض التوضيحي. سجّل الدخول لحفظ بيانات مؤسستك.');setModal({type:'auth'});return false}saving.current=true;setBusy(true);try{if(!navigator.onLine)throw Error('يلزم الاتصال بالإنترنت لحفظ العملية. لم تُحفظ أي عملية دون اتصال.');const r=await authenticatedFetch(`/api/${path}`,{method,headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw Object.assign(Error(j.error),{status:r.status});const refreshed=await load(true);notify(refreshed?'تم حفظ العملية ومزامنة البيانات بنجاح':'تم حفظ العملية. تعذر تحديث العرض؛ يُعاد التحديث عند عودة الاتصال.');return j}catch(e){notify(e.status?e.message:'تعذر تأكيد نتيجة الحفظ. أعد المحاولة من النموذج نفسه دون تحديث الصفحة؛ إذا أغلقتها فتحقق من السجل أولاً.');return false}finally{saving.current=false;setBusy(false)}}
