 const allowed=key=>isDemo||data.role==='admin'||key==='overview'||({warehouse:['inventory','reports'],sales:['inventory','sales','quotes','invoices','customers','reports'],finance:['finance','invoices','customers','reports']}[data.role]||[]).includes(key);
