 function exportCSV(rows,name){if(!rows.length){notify('لا توجد بيانات للتصدير');return}const keys=Object.keys(rows[0]);const safe=v=>{const s=String(v??'');return /^[=+\-@\t\r]/.test(s)?`'${s}`:s};const content='\uFEFF'+[keys,...rows.map(r=>keys.map(k=>safe(r[k])))].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`${name}.csv`;a.click();URL.revokeObjectURL(url);notify('تم تصدير الملف بنجاح')}
