 {['sales','invoices','quotes'].includes(page)&&<><div className="compact-stats"><Mini label={page==='quotes'?'قيمة عروض الأسعار':'إجمالي المبيعات'} value={money((page==='quotes'?quotes:invoices).reduce((a,d)=>a+Number(d.total),0))}/><Mini label="عدد المستندات" value={(page==='quotes'?quotes:invoices).length}/><Mini label={page==='quotes'?'عروض نشطة':'المستحق للتحصيل'} value={page==='quotes'?quotes.filter(q=>q.status==='active').length:money(due)}/></div><section className="panel"><div className="list-toolbar"><div className="tabs">{['الكل',...(page==='quotes'?['active','converted']:['paid','partial','unpaid'])].map(s=><button key={s} className={filter===s?'active':''} onClick={()=>setFilter(s)}>{statusNames[s]||s}</button>)}</div><SearchBox value={search} onChange={setSearch} placeholder="رقم المستند أو اسم العميل…"/></div><DocumentTable docs={docs} money={money} onView={d=>open('view',{doc:d})} full/>{!docs.length&&<Empty text="لا توجد مستندات. ابدأ بإنشاء مستند جديد."/>}<div className="table-footer">{docs.length} مستند<span>السجلات محفوظة في قاعدة بيانات موحدة</span></div></section></>}
