 {page==='customers'&&<section className="panel"><div className="list-toolbar"><h3>دليل العملاء <span className="count-badge">{data.customers.length}</span></h3><SearchBox value={search} onChange={setSearch} placeholder="ابحث عن عميل…"/></div><div className="customer-grid">{data.customers.filter(c=>`${c.name} ${c.phone}`.includes(search)).map((c,i)=><button className="customer-card" key={c.id} onClick={()=>open('customerView',{customer:c})}><span className={`customer-avatar c${i%3}`}>{c.name.slice(0,1)}</span><h3>{c.name}</h3><p>{c.address||'لم يحدد العنوان'}</p><span className="latin">{c.phone||'—'}</span><div><span>إجمالي المشتريات</span><b>{money(invoices.filter(d=>d.customerId===c.id).reduce((a,d)=>a+Number(d.total),0))}</b></div></button>)}</div>{!data.customers.length&&<Empty text="أضف أول عميل لبدء تسجيل المبيعات"/>}</section>}
