 {['password','invite'].includes(modal.type)&&<><h2>تعيين كلمة المرور</h2><form onSubmit={async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.currentTarget));if(b.password!==b.confirmPassword){notify('كلمتا المرور غير متطابقتين');return}setBusy(true);if(modal.type==='invite'){const u=await acceptInviteSession({acceptInvite,login},modal.token,b.password);setSession(u);history.replaceState(null,'',location.pathname)}else{await updateUser({password:b.password});setSession(await getUser())}setModal(null);notify('تم تعيين كلمة المرور');await load()}catch(error){if(error.code==='INVITE_ACCEPTED_LOGIN_PENDING'){setModal(null);history.replaceState(null,'',location.pathname);setAuthMode('login');setAuthMsg(error.message)}notify(error.message?.startsWith('تم قبول الدعوة')||error.message?.startsWith('تعذر استكمال الدخول')?error.message:'تعذر تعيين كلمة المرور. تحقق من الاتصال وصلاحية الرابط، ثم أعد المحاولة.')}finally{setBusy(false)}}}><Field label="كلمة المرور الجديدة" name="password" type="password" minLength="8" required autoComplete="new-password"/><Field label="تأكيد كلمة المرور الجديدة" name="confirmPassword" type="password" minLength="8" required autoComplete="new-password"/><button className="btn primary" disabled={busy}>{busy?'جارٍ الحفظ…':'حفظ كلمة المرور'}</button></form></>}
 {modal.type==='product'&&<><ModalHeading icon={Package} title={modal.product?"تعديل بيانات المادة":"إضافة مادة جديدة"} subtitle={modal.product?"تحديث المادة لا يغير الفواتير السابقة أو الرصيد الحالي.":"أضف تفاصيل المادة ورصيدها الافتتاحي."}/><form onSubmit={async e=>{e.preventDefault();if(await mutate(modal.product?`products/${modal.product.id}`:'products',Object.fromEntries(new FormData(e.currentTarget)),modal.product?'PUT':'POST'))setModal(null)}}><div className="form-grid"><Field label="اسم المادة" name="name" defaultValue={modal.product?.name} required className="wide"/><Field label="رمز المادة SKU" name="sku" defaultValue={modal.product?.sku} required/><label className="field">الفئة<select name="category" defaultValue={modal.product?.category}>{categories.map(c=><option key={c}>{c}</option>)}</select></label><Field label={`سعر البيع (${currency})`} name="price" type="number" min="0" step="0.01" defaultValue={modal.product?.price} required/><Field label={`سعر الكلفة (${currency})`} name="cost" type="number" min="0" step="0.01" defaultValue={modal.product?.cost||0}/>{!modal.product&&<Field label="الرصيد الافتتاحي" name="stock" type="number" min="0" step="1" defaultValue="0" required/>}<Field label="الحد الأدنى للتنبيه" name="minimum" type="number" min="0" step="1" defaultValue={modal.product?.minimum??10} required/><Field label="وحدة القياس" name="unit" defaultValue={modal.product?.unit||"قطعة"} required/></div><Submit busy={busy}/></form></>}
